package realestate.service;
import realestate.dao.PropertyDAO;import realestate.model.*;import java.sql.SQLException;import java.math.BigDecimal;import java.util.List;
public class PropertyService {private final PropertyDAO dao;public PropertyService(PropertyDAO d){dao=d;}public long add(Property x)throws SQLException{validate(x);return dao.add(x);}public boolean update(Property x,long actor,boolean admin)throws SQLException{validate(x);return dao.update(x,actor,admin);}public boolean deactivate(long id,long actor,boolean admin)throws SQLException{if(id<1)throw new IllegalArgumentException("ID must be positive");return dao.deactivate(id,actor,admin);}public List<Property> search(String loc,String type,BigDecimal max,int beds)throws SQLException{if(max!=null&&max.signum()<0)throw new IllegalArgumentException("Maximum price cannot be negative");return dao.search(loc,type,max,beds);}private void validate(Property x){if(x.getTitle().isBlank()||x.getLocation().isBlank()||x.getPrice().signum()<=0||x.getArea()<=0||x.getBedrooms()<0||x.getBathrooms()<0)throw new IllegalArgumentException("Title and location are required; price/area must be positive and bedroom/bath counts cannot be negative.");}}
